<?php
require __DIR__.'/../../includes/bootstrap.php';require_once __DIR__.'/../../services/QueueService.php';music_api_post();$user=music_current_user($mysqli,true);music_api_csrf();$id=(int)($_POST['track_id']??0);$scope=(string)($_POST['scope']??'ALL');if(!in_array($scope,['ALL','AUDIO','COVER'],true))music_json(['ok'=>false,'message'=>'Opção inválida.'],422);$track=music_require_owned_track($mysqli,$id,(int)$user['id']);if(in_array($track['status'],['GENERATING','QUEUED'],true))music_json(['ok'=>false,'message'=>'Já existe uma geração em andamento.'],409);
$types=$scope==='ALL'?['AUDIO','COVER']:[$scope];$mysqli->begin_transaction();try{foreach($types as $type){$stmt=$mysqli->prepare('SELECT id,storage_path FROM music_ai_media WHERE track_id=? AND media_type=?');$stmt->bind_param('is',$id,$type);$stmt->execute();$media=$stmt->get_result()->fetch_assoc();$stmt->close();if($media&&is_file($media['storage_path']))@rename($media['storage_path'],$media['storage_path'].'.obsolete-'.date('YmdHis'));if($media){$mid=(int)$media['id'];$stmt=$mysqli->prepare('DELETE FROM music_ai_media WHERE id=?');$stmt->bind_param('i',$mid);$stmt->execute();$stmt->close();}}
$audioReset=in_array('AUDIO',$types,true);$coverReset=in_array('COVER',$types,true);if($audioReset){$stmt=$mysqli->prepare("UPDATE music_ai_tracks SET status='QUEUED',is_published=0,published_at=NULL,audio_media_id=NULL,audio_generated_at=NULL,audio_validated_at=NULL,audio_uploaded_at=NULL,generation_state=NULL,current_stage='Nova geração na fila',progress_percent=30,last_error=NULL WHERE id=?");}else{$stmt=$mysqli->prepare("UPDATE music_ai_tracks SET status='QUEUED',is_published=0,published_at=NULL,cover_media_id=NULL,cover_generated_at=NULL,cover_uploaded_at=NULL,generation_state=NULL,current_stage='Nova capa na fila',progress_percent=78,last_error=NULL WHERE id=?");}$stmt->bind_param('i',$id);$stmt->execute();$stmt->close();$key='track:regenerate:'.$id.':'.bin2hex(random_bytes(8));(new QueueService($mysqli))->enqueue((int)$user['id'],$id,$key,'PIPELINE',['regeneration_scope'=>$scope]);$mysqli->commit();music_json(['ok'=>true,'message'=>'Nova geração colocada na fila.']);}catch(Throwable $e){$mysqli->rollback();music_json(['ok'=>false,'message'=>'Não foi possível iniciar uma nova geração.'],500);}
